import React, { useState, useMemo, useRef, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { calcAllAbilities } from '../lib/genAbilities';
import { getTeamDisplayColor } from '../utils';
import styles from './AdminPage.module.css';

// ── 능력치 컬럼 정의 ──
const PITCHER_COLS = ['control', 'stuff', 'stamina', 'command'];
const BATTER_COLS  = ['contact', 'discipline', 'power', 'speed'];

const COL_LABEL = {
  control: '제구', stuff: '구위', stamina: '체력', command: '커맨드',
  contact: '컨택', discipline: '선구안', power: '파워', speed: '주력',
};

function isPitcher(position) {
  if (!position) return false;
  return position.split('/').some(p => ['P','SP','RP','CP'].includes(p.trim()));
}

function getAbilityCols(player) {
  return isPitcher(player.position) ? PITCHER_COLS : BATTER_COLS;
}

function abilityColor(val) {
  if (val == null) return '#999';
  if (val >= 80) return '#e53935';
  if (val >= 70) return '#FB8C00';
  if (val >= 60) return '#43A047';
  if (val >= 50) return '#1E88E5';
  return '#888';
}

// ── 단일 편집 가능 셀 ──
function EditCell({ value, onSave }) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState('');
  const inputRef = useRef(null);

  const startEdit = () => {
    setDraft(String(value ?? ''));
    setEditing(true);
    setTimeout(() => inputRef.current?.select(), 0);
  };

  const commit = () => {
    const n = parseInt(draft, 10);
    if (!isNaN(n) && n >= 1 && n <= 100 && n !== value) {
      onSave(n);
    }
    setEditing(false);
  };

  const handleKey = (e) => {
    if (e.key === 'Enter') commit();
    if (e.key === 'Escape') setEditing(false);
  };

  if (editing) {
    return (
      <input
        ref={inputRef}
        className={styles.cellInput}
        value={draft}
        onChange={e => setDraft(e.target.value)}
        onBlur={commit}
        onKeyDown={handleKey}
        type="number"
        min="1"
        max="100"
      />
    );
  }

  return (
    <span
      className={styles.cellVal}
      style={{ color: abilityColor(value) }}
      onClick={startEdit}
      title="클릭하여 편집"
    >
      {value ?? '—'}
    </span>
  );
}

// ── 메인 컴포넌트 ──
export default function AdminPage({ players: initialPlayers, teams, teamsMap, loading }) {
  const [players, setPlayers] = useState(initialPlayers);
  const [dirtyMap, setDirtyMap] = useState({}); // player_id → { col: newVal }
  const [saving, setSaving] = useState(null);   // player_id currently saving
  const [savedSet, setSavedSet] = useState(new Set());
  const [filterTeam, setFilterTeam] = useState('ALL');
  const [filterType, setFilterType] = useState('ALL');
  const [search, setSearch] = useState('');
  const [importStatus, setImportStatus] = useState('');
  const [recalcStatus, setRecalcStatus] = useState('');
  const fileInputRef = useRef(null);

  // initialPlayers prop이 바뀌면 동기화 (useData 로딩 완료 후)
  const prevInitial = useRef(null);
  if (initialPlayers !== prevInitial.current) {
    prevInitial.current = initialPlayers;
    setPlayers(initialPlayers);
  }

  // ── 필터링 ──
  const filtered = useMemo(() => {
    let list = players;
    if (filterTeam !== 'ALL') list = list.filter(p => p.team_id === filterTeam);
    if (filterType === 'pitcher') list = list.filter(p => isPitcher(p.position));
    if (filterType === 'batter')  list = list.filter(p => !isPitcher(p.position));
    if (filterType === 'manual')  list = list.filter(p => p.is_manual);
    if (search.trim()) {
      const q = search.trim().toLowerCase();
      list = list.filter(p =>
        p.name_kor?.toLowerCase().includes(q) ||
        (p.name_eng && p.name_eng.toLowerCase().includes(q))
      );
    }
    return list;
  }, [players, filterTeam, filterType, search]);

  // ── 드래프트 업데이트 ──
  const handleEdit = useCallback((playerId, col, val) => {
    setDirtyMap(prev => ({
      ...prev,
      [playerId]: { ...(prev[playerId] || {}), [col]: val },
    }));
    setPlayers(prev => prev.map(p =>
      String(p.id) === String(playerId) ? { ...p, [col]: val } : p
    ));
  }, []);

  // ── 개별 저장 ──
  const handleSave = useCallback(async (player) => {
    const id = String(player.id);
    const dirty = dirtyMap[id];
    if (!dirty || Object.keys(dirty).length === 0) return;

    setSaving(id);
    try {
      const { error } = await supabase
        .from('player_abilities')
        .upsert({
          player_id: id,
          ...dirty,
          is_manual: true,
          source: 'manual',
          updated_at: new Date().toISOString(),
        }, { onConflict: 'player_id' });

      if (error) throw error;

      // 로컬 상태 is_manual 반영
      setPlayers(prev => prev.map(p =>
        String(p.id) === id ? { ...p, is_manual: true } : p
      ));
      setDirtyMap(prev => { const n = { ...prev }; delete n[id]; return n; });
      setSavedSet(prev => new Set([...prev, id]));
      setTimeout(() => setSavedSet(prev => { const n = new Set(prev); n.delete(id); return n; }), 2000);
    } catch (err) {
      alert(`저장 실패: ${err.message}`);
    }
    setSaving(null);
  }, [dirtyMap]);

  // ── 수동 보정 해제 ──
  const handleResetManual = useCallback(async (player) => {
    const id = String(player.id);
    if (!window.confirm(`${player.name_kor}의 수동 보정을 해제하고 자동 생성 능력치로 되돌리시겠습니까?`)) return;

    setSaving(id);
    try {
      const { error } = await supabase
        .from('player_abilities')
        .update({ is_manual: false, source: 'generated', updated_at: new Date().toISOString() })
        .eq('player_id', id);
      if (error) throw error;

      setPlayers(prev => prev.map(p =>
        String(p.id) === id ? { ...p, is_manual: false } : p
      ));
    } catch (err) {
      alert(`초기화 실패: ${err.message}`);
    }
    setSaving(null);
  }, []);

  // ── 능력치 재계산 (Supabase player_season_stats 기반) ──
  const handleRecalc = useCallback(async () => {
    if (!window.confirm('player_season_stats 데이터를 읽어 능력치를 재계산합니다.\n수동 보정(is_manual) 선수는 건너뜁니다. 진행할까요?')) return;

    setRecalcStatus('📥 시즌 스탯 불러오는 중...');
    try {
      // 1. 수동 보정 선수 조회
      const { data: manualList, error: mErr } = await supabase
        .from('player_abilities')
        .select('player_id')
        .eq('is_manual', true);
      if (mErr) throw mErr;
      const manualIds = new Set((manualList || []).map(r => String(r.player_id)));

      // 2. player_season_stats 전체 조회 (페이지네이션 고려)
      let allStats = [];
      let from = 0;
      const PAGE = 1000;
      while (true) {
        const { data, error } = await supabase
          .from('player_season_stats')
          .select('*')
          .range(from, from + PAGE - 1);
        if (error) throw error;
        allStats = allStats.concat(data || []);
        if (!data || data.length < PAGE) break;
        from += PAGE;
        setRecalcStatus(`📥 시즌 스탯 불러오는 중... ${allStats.length}행`);
      }

      setRecalcStatus(`⚙️ 능력치 계산 중... (${allStats.length}행)`);

      // 3. 계산
      const results = calcAllAbilities(players, allStats);

      // 4. 수동 보정 선수 제외
      const batch = results.filter(r => !manualIds.has(String(r.player_id)));
      const skipped = results.length - batch.length;

      // 5. Supabase upsert
      const BATCH_SIZE = 100;
      let done = 0;
      for (let i = 0; i < batch.length; i += BATCH_SIZE) {
        const chunk = batch.slice(i, i + BATCH_SIZE);
        const { error } = await supabase
          .from('player_abilities')
          .upsert(chunk, { onConflict: 'player_id' });
        if (error) throw error;
        done += chunk.length;
        setRecalcStatus(`💾 저장 중... ${done} / ${batch.length}`);
      }

      setRecalcStatus(`✅ 완료 — 재계산: ${batch.length}명 / 스킵(수동): ${skipped}명`);

      // 6. 로컬 상태 갱신
      setPlayers(prev => {
        const map = {};
        batch.forEach(r => { map[r.player_id] = r; });
        return prev.map(p => {
          const upd = map[String(p.id)];
          if (!upd) return p;
          return { ...p, ...upd };
        });
      });
    } catch (err) {
      setRecalcStatus(`❌ 오류: ${err.message}`);
    }
  }, [players]);

  // ── Bulk Import ──
  const handleImportFile = useCallback(async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    e.target.value = '';

    setImportStatus('파일 읽는 중...');
    try {
      const text = await file.text();
      const data = JSON.parse(text);

      // gen_abilities 출력 형식: { teamName: { players: [...] } }
      const allPlayers = [];
      Object.values(data).forEach(team => {
        (team.players || []).forEach(p => allPlayers.push(p));
      });

      if (!allPlayers.length) {
        setImportStatus('❌ 선수 데이터 없음');
        return;
      }

      setImportStatus('🔒 수동 보정 선수 조회 중...');
      const { data: manualList, error: mErr } = await supabase
        .from('player_abilities')
        .select('player_id')
        .eq('is_manual', true);
      if (mErr) throw mErr;

      const manualIds = new Set((manualList || []).map(r => String(r.player_id)));

      const batch = [];
      let skipped = 0;
      allPlayers.forEach(player => {
        const id = String(player.id);
        if (manualIds.has(id)) { skipped++; return; }
        if (!player.abilities) return;
        const ab = player.abilities;
        batch.push({
          player_id:  id,
          control:    ab.control    ?? null,
          stuff:      ab.stuff      ?? null,
          stamina:    ab.stamina    ?? null,
          command:    ab.command    ?? null,
          contact:    ab.contact    ?? null,
          discipline: ab.discipline ?? null,
          power:      ab.power      ?? null,
          speed:      ab.speed      ?? null,
          source:     'generated',
          is_manual:  false,
          updated_at: new Date().toISOString(),
        });
      });

      const BATCH_SIZE = 100;
      let done = 0;
      for (let i = 0; i < batch.length; i += BATCH_SIZE) {
        const chunk = batch.slice(i, i + BATCH_SIZE);
        const { error } = await supabase
          .from('player_abilities')
          .upsert(chunk, { onConflict: 'player_id' });
        if (error) throw error;
        done += chunk.length;
        setImportStatus(`📦 업데이트 중... ${done} / ${batch.length}`);
      }

      setImportStatus(`✅ 완료 — 업데이트: ${batch.length}명 / 스킵(수동): ${skipped}명`);

      // 로컬 상태 갱신
      setPlayers(prev => {
        const map = {};
        batch.forEach(r => { map[r.player_id] = r; });
        return prev.map(p => {
          const upd = map[String(p.id)];
          if (!upd) return p;
          return { ...p, ...upd };
        });
      });
    } catch (err) {
      setImportStatus(`❌ 오류: ${err.message}`);
    }
  }, []);

  // ── UI ──
  const manualCount = players.filter(p => p.is_manual).length;

  return (
    <div className={styles.wrap}>
      {/* ── 헤더 ── */}
      <header className={styles.header}>
        <div className={styles.headerLeft}>
          <span className={styles.adminBadge}>ADMIN</span>
          <h1 className={styles.title}>관리자 콘솔</h1>
          <span className={styles.subInfo}>수동 보정: {manualCount}명</span>
        </div>
        <a className={styles.backBtn} href={window.location.pathname}>
          ← 메인으로
        </a>
      </header>

      {/* ── 툴바 ── */}
      <div className={styles.toolbar}>
        {/* 팀 필터 */}
        <select className={styles.select} value={filterTeam} onChange={e => setFilterTeam(e.target.value)}>
          <option value="ALL">전체 팀</option>
          {teams.map(t => (
            <option key={t.id} value={t.id}>{t.name_kor}</option>
          ))}
        </select>

        {/* 유형 필터 */}
        <select className={styles.select} value={filterType} onChange={e => setFilterType(e.target.value)}>
          <option value="ALL">전체</option>
          <option value="pitcher">투수</option>
          <option value="batter">타자</option>
          <option value="manual">수동 보정만</option>
        </select>

        {/* 검색 */}
        <input
          className={styles.searchInput}
          placeholder="선수 이름 검색..."
          value={search}
          onChange={e => setSearch(e.target.value)}
        />

        <div className={styles.spacer} />

        {/* Bulk Import */}
        <div className={styles.importArea}>
          {/* 능력치 재계산 */}
          <button
            className={styles.recalcBtn}
            onClick={handleRecalc}
          >
            ⚡ 능력치 재계산
          </button>
          {recalcStatus && <span className={styles.importStatus}>{recalcStatus}</span>}

          <div className={styles.divider} />

          {/* gen_abilities JSON Import */}
          <button
            className={styles.importBtn}
            onClick={() => fileInputRef.current?.click()}
          >
            📂 JSON Import
          </button>
          <input
            ref={fileInputRef}
            type="file"
            accept=".json"
            style={{ display: 'none' }}
            onChange={handleImportFile}
          />
          {importStatus && <span className={styles.importStatus}>{importStatus}</span>}
        </div>
      </div>

      {/* ── 로딩 ── */}
      {loading && <div className={styles.loadingMsg}>로딩 중...</div>}

      {/* ── 테이블 ── */}
      {!loading && (
        <div className={styles.tableWrap}>
          <table className={styles.table}>
            <thead>
              <tr>
                <th className={styles.th}>팀</th>
                <th className={styles.th}>이름</th>
                <th className={styles.th}>포지션</th>
                <th className={`${styles.th} ${styles.abilityHead}`}>제구/구위/체력/커맨드<br />컨택/선구안/파워/주력</th>
                <th className={styles.th}>상태</th>
                <th className={styles.th}>액션</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map(player => {
                const id = String(player.id);
                const team = teamsMap[player.team_id];
                const teamColor = getTeamDisplayColor(team);
                const cols = getAbilityCols(player);
                const isDirty = !!(dirtyMap[id] && Object.keys(dirtyMap[id]).length);
                const isSavingThis = saving === id;
                const isSaved = savedSet.has(id);

                return (
                  <tr key={id} className={`${styles.row} ${player.is_manual ? styles.rowManual : ''}`}>
                    {/* 팀 */}
                    <td className={styles.td}>
                      <span
                        className={styles.teamDot}
                        style={{ background: teamColor }}
                      />
                    </td>

                    {/* 이름 */}
                    <td className={styles.td}>
                      <div className={styles.nameKor}>{player.name_kor}</div>
                      {player.name_eng && (
                        <div className={styles.nameEng}>{player.name_eng}</div>
                      )}
                    </td>

                    {/* 포지션 */}
                    <td className={styles.td}>
                      <span className={`${styles.posBadge} ${isPitcher(player.position) ? styles.posPitcher : styles.posBatter}`}>
                        {player.position || '—'}
                      </span>
                    </td>

                    {/* 능력치 셀들 */}
                    <td className={styles.td}>
                      <div className={styles.abilityCells}>
                        {cols.map(col => (
                          <div key={col} className={styles.abilityItem}>
                            <span className={styles.abilityLabel}>{COL_LABEL[col]}</span>
                            <EditCell
                              value={player[col]}
                              onSave={val => handleEdit(id, col, val)}
                            />
                          </div>
                        ))}
                      </div>
                    </td>

                    {/* 상태 배지 */}
                    <td className={styles.td}>
                      {player.is_manual && (
                        <span className={styles.manualBadge} title="수동 보정됨">수동</span>
                      )}
                      {isSaved && (
                        <span className={styles.savedBadge}>저장됨 ✓</span>
                      )}
                    </td>

                    {/* 액션 버튼 */}
                    <td className={styles.td}>
                      <div className={styles.actions}>
                        {isDirty && (
                          <button
                            className={styles.saveBtn}
                            onClick={() => handleSave(player)}
                            disabled={isSavingThis}
                          >
                            {isSavingThis ? '저장 중...' : '저장'}
                          </button>
                        )}
                        {player.is_manual && (
                          <button
                            className={styles.resetBtn}
                            onClick={() => handleResetManual(player)}
                            disabled={isSavingThis}
                          >
                            자동 복원
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>

          {filtered.length === 0 && (
            <div className={styles.emptyMsg}>검색 결과가 없습니다.</div>
          )}
        </div>
      )}

      <div className={styles.footer}>
        총 {filtered.length}명 표시 중 (전체 {players.length}명)
      </div>
    </div>
  );
}
